classDiagram
    class Calculator {
        +calculate(expression: str) -> str
    }
    class ExpressionParser {
        +parse(expression: str) -> List[Token]
    }
    class ShuntingYard {
        +to_postfix(tokens: List[Token]) -> List[Token]
    }
    class PostfixEvaluator {
        +evaluate(postfix: List[Token]) -> float
    }
    class Token {
        -type: str
        -value: Any
        +__init__(type: str, value: Any)
    }
    class Operator {
        -symbol: str
        -precedence: int
        -associativity: str
        +__init__(symbol: str, precedence: int, associativity: str)
    }
    class CLI {
        +run()
    }
    Calculator --> ExpressionParser
    Calculator --> ShuntingYard
    Calculator --> PostfixEvaluator
    ExpressionParser --> Token
    ShuntingYard --> Token
    PostfixEvaluator --> Token
    ShuntingYard --> Operator
    CLI --> Calculator
```

